Mesh<Point, double> mesh;

for (auto fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
    const auto &facet = *fit;                     // facet = (Cell_handle, int)
    const auto cell   = facet.first;
    int       i       = facet.second;

    const auto neighbor = cell->neighbor(i);
    if (rt.is_infinite(cell) || rt.is_infinite(neighbor)) continue;

    const Point p1 = rt.dual(cell);
    const Point p2 = rt.dual(neighbor);

    const double sq_len = CGAL::squared_distance(p1, p2);
    if (sq_len > threshold * threshold) continue;

    mesh.add_edge(p1, p2);
}

/* compute face (cell) areas */
for (auto cit = rt.finite_cells_begin(); cit != rt.finite_cells_end(); ++cit) {
    const auto cell = *cit;
    if (rt.is_infinite(cell)) continue;

    std::vector<Point> verts;
    for (int i = 0; i < 3; ++i) {                 // 2‑D regular triangulation: 3 facets per cell
        const auto nb = cell->neighbor(i);
        if (rt.is_infinite(nb)) continue;
        verts.push_back(rt.dual(nb));
    }
    if (verts.size() < 3) continue;               // not a polygon

    // compute centroid for angular sorting
    double cx = 0.0, cy = 0.0;
    for (const auto &v : verts) {
        cx += v.x();
        cy += v.y();
    }
    cx /= static_cast<double>(verts.size());
    cy /= static_cast<double>(verts.size());

    std::sort(verts.begin(), verts.end(),
        [&](const Point &a, const Point &b) {
            const double angA = std::atan2(a.y() - cy, a.x() - cx);
            const double angB = std::atan2(b.y() - cy, b.x() - cx);
            return angA < angB;
        });

